__NUXT_JSONP__("/jp/how-to-apply-for-a-student-visa", {data:[{details:{slug:"jp",pageTitle:"学生ビザの申請方法 | Mentor Language Institute",pageDescription:"学生ビザ（F1ビザ）を申請するにはいくつかのステップがあります。 ",title:"学生ビザの申請方法",subtitle:["学生ビザ（F1ビザ）を申請するにはいくつかのステップがあります。これらの手順と順序、完了方法は、各国の米国大使館または領事館によって異なる場合があります。\u003Ca href=\"https:\u002F\u002Fwww.usembassy.gov\u002F\" target=\"_blank\"\u003E大使館または領事館のウェブサイトの案内を参照してください。\u003C\u002Fa\u003E","ビデオ：以下の学生ビザ案内ビデオは、学生ビザを申請して取得するための一般的な手順を示しています。"],yt_link:"https:\u002F\u002Fwww.youtube.com\u002Fembed\u002F3OB74QSQKJM",other_description:["以下のリンクからプレゼンテーション資料をダウンロードできます。","\u003Ca href=\"\u002Fdocuments\u002FHow_to_apply_for_a_student-visa_JP2021.pdf\"\u003E\u003Cstrong\u003E学生ビザ申請案内プレゼンテーション資料をダウンロード\u003C\u002Fstrong\u003E\u003C\u002Fa\u003E"],dir:"\u002Fhow-to-apply-for-a-student-visa",path:"\u002Fhow-to-apply-for-a-student-visa\u002Fjp",extension:".json",createdAt:"2026-10-22T16:31:29.671Z",updatedAt:"2025-05-26T12:06:27.787Z"}}],fetch:{},mutations:void 0});